package com.google.javascript.rhino;

import com.google.common.base.Preconditions;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class IR_tryCatch_TriageGen1Test {

    @Test
    public void testTryCatchSuccess() {
        // Create a valid try body (must be a block)
        Node tryBody = IR.block(IR.returnNode());

        // Create a valid catch node (must be a catch node)
        // Using IR.catchNode helper to ensure it is a valid catch node
        Node catchNode = IR.catchNode(IR.name("e"), IR.block(IR.returnNode()));

        // Execute the method under test
        Node result = IR.tryCatch(tryBody, catchNode);

        // Assertions
        assertNotNull(result);
        assertEquals(Token.TRY, result.getType());
        assertEquals(tryBody, result.getFirstChild());

        // The catch body is created via block(catchNode).copyInformationFrom(catchNode)
        // We verify the second child is a block and contains the information from catchNode
        Node catchBody = result.getNextSibling(); // In Rhino IR, try-catch structure: TRY -> [tryBody, catchBody]
        // Note: Based on the implementation: return new Node(Token.TRY, tryBody, catchBody);
        // The structure is TRY(tryBody, catchBody)
        assertEquals(tryBody, result.getFirstChild());
        assertEquals(catchBody, result.getNextSibling());

        // Verify catchBody preserves information from the original catchNode
        // Since we can't easily check private info, we check the type/structure
        assertNotNull(catchBody);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchThrowsWhenTryBodyIsNotBlock() {
        // tryBody must be a block. We provide an expression instead.
        Node tryBody = IR.number(1); 
        Node catchNode = IR.catchNode(IR.name("e"), IR.block());

        IR.tryCatch(tryBody, catchNode);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchThrowsWhenCatchNodeIsNotCatch() {
        // catchNode must be a catch node. We provide a block instead.
        Node tryBody = IR.block();
        Node catchNode = IR.block(); 

        IR.tryCatch(tryBody, catchNode);
    }

    @Test
    public void testTryCatchStructureIntegrity() {
        // Detailed check of the resulting node hierarchy
        Node tryBody = IR.block(IR.var(IR.name("x"), IR.number(1)));
        Node catchNode = IR.catchNode(IR.name("e"), IR.block(IR.throwNode(IR.name("e"))));

        Node result = IR.tryCatch(tryBody, catchNode);

        assertEquals(Token.TRY, result.getType());

        // Verify tryBody is the first child
        Node firstChild = result.getFirstChild();
        assertEquals(tryBody, firstChild);
        assertEquals(Token.BLOCK, firstChild.getType());

        // Verify catchBody is the second child
        Node secondChild = result.getNextSibling();
        assertNotNull(secondChild);
        assertEquals(Token.BLOCK, secondChild.getType());
    }
}
